package mz.bam.seeky.android;
import android.app.*;import android.content.*;import android.database.Cursor;import android.view.*;import android.widget.*;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;import java.util.*;import java.util.concurrent.atomic.AtomicBoolean;import org.json.*;
/** Local resumable retrieval practice. A stable review token also recovers a crash after grading. */
final class StudyReview {
 static final String KEY="review_session_v1";final StudyHub h;final MainActivity a;JSONObject state;
 StudyReview(StudyHub h){this.h=h;a=h.a;}
 static JSONObject saved(SharedPreferences p){try{String value=p.getString(KEY,"");if(value.isEmpty()||value.length()>32768)return null;JSONObject s=new JSONObject(value);JSONArray q=s.getJSONArray("queue");int at=s.getInt("at");if(!s.getString("token").matches("[a-f0-9-]{36}")||q.length()<1||q.length()>40||at<0||at>q.length()||s.getLong("course")<0||s.getLong("subject")<0||s.getJSONArray("grades").length()!=4)return null;for(int i=0;i<q.length();i++){JSONObject row=q.getJSONObject(i);if(row.getLong("id")<=0||row.getLong("updated")<0||!row.getString("fingerprint").matches("[a-f0-9]{64}"))return null;}int graded=0;for(int i=0;i<4;i++){int n=s.getJSONArray("grades").getInt(i);if(n<0||n>40)return null;graded+=n;}if(s.optInt("skipped")<0||graded+s.optInt("skipped")!=at)return null;return s;}catch(Exception e){return null;}}
 static boolean pending(SharedPreferences p){JSONObject s=saved(p);return s!=null&&s.optInt("at")<s.optJSONArray("queue").length();}
 static boolean pendingFor(SharedPreferences p,long course,long subject){JSONObject s=saved(p);return s!=null&&s.optInt("at")<s.optJSONArray("queue").length()&&(subject>0?s.optLong("subject")==subject:course==0||s.optLong("course")==course);}
 static String fingerprint(StudyStore.Row row){try{byte[] digest=MessageDigest.getInstance("SHA-256").digest((row.n("subject")+"\n"+row.s("front")+"\u0000"+row.s("back")).getBytes(StandardCharsets.UTF_8));StringBuilder text=new StringBuilder();for(byte b:digest)text.append(String.format(Locale.ROOT,"%02x",b&255));return text.toString();}catch(Exception e){throw new IllegalStateException(e);}}
 void options(){JSONObject previous=saved(h.prefs);if(previous!=null&&previous.optInt("at")<previous.optJSONArray("queue").length()){a.dialog().setTitle("Revisão em pausa").setMessage(previous.optString("title")+" · "+previous.optInt("at")+" / "+previous.optJSONArray("queue").length()+"\n\nUma nova revisão substitui apenas esta fila. As avaliações já guardadas permanecem.").setPositiveButton("Retomar revisão",(d,w)->resume()).setNeutralButton("Nova revisão",(d,w)->choose()).setNegativeButton("Fechar",null).show();}else choose();}
 void choose(){a.dialog().setTitle("Preparar revisão").setMessage("Escolha uma sessão curta. Só entram cartões devidos do curso ou disciplina actual; cartões pausados ficam de fora.").setItems(new String[]{"Até 10 cartões","Até 20 cartões","Até 40 cartões"},(d,n)->start(new int[]{10,20,40}[n])).setNegativeButton("Cancelar",null).show();}
 void persist(JSONObject s){if(!h.prefs.edit().putString(KEY,s.toString()).commit())throw new IllegalStateException("Não foi possível guardar a revisão. Liberte espaço e tente novamente.");}
 void start(int limit){final long course=h.course,subject=h.subject;final String title=subject>0?h.subjectName(subject):h.courseName();h.job(()->{List<StudyStore.Row> rows=h.db.rows("cards",StudyStore.scope(course,subject)+" AND suspended=0 AND due<=?",new String[]{""+System.currentTimeMillis()},"due,id",Math.max(1,Math.min(40,limit)));if(rows.isEmpty()){a.ui(()->a.dialog().setTitle("Revisões em dia").setMessage("Não há cartões devidos neste filtro. Pode criar cartões ou marcar um cartão para rever hoje.").setPositiveButton("Criar cartão",(d,w)->h.cardForm(null,0,0,"","")).setNegativeButton("Fechar",null).show());return;}try{JSONArray queue=new JSONArray();for(StudyStore.Row row:rows)queue.put(new JSONObject().put("id",row.id()).put("updated",row.n("updated")).put("fingerprint",fingerprint(row)));JSONObject s=new JSONObject().put("token",UUID.randomUUID().toString()).put("course",course).put("subject",subject).put("title",title).put("at",0).put("skipped",0).put("grades",new JSONArray(new int[]{0,0,0,0})).put("queue",queue);persist(s);state=s;step();}catch(JSONException e){throw new IllegalStateException(e);}});}
 void resume(){h.job(()->{state=saved(h.prefs);if(state==null){a.ui(()->a.toast("Não há uma revisão válida para retomar."));return;}step();});}
 // Runs on StudyHub's worker. The queue contains identities, never stale answer snapshots.
 void step(){try{JSONArray queue=state.getJSONArray("queue");while(state.getInt("at")<queue.length()){int at=state.getInt("at");JSONObject entry=queue.getJSONObject(at);StudyStore.Row card=h.db.get("cards",entry.getLong("id"));String token=state.getString("token")+":"+at;int recovered=-1;try(Cursor c=h.db.getReadableDatabase().query("reviews",new String[]{"grade","card"},"token=?",new String[]{token},null,null,null)){if(c.moveToFirst()&&c.getLong(1)==entry.getLong("id"))recovered=c.getInt(0);}if(recovered>=0&&recovered<=3){advance(state,recovered);persist(state);continue;}if(card==null||card.n("suspended")!=0||card.n("updated")!=entry.getLong("updated")||!fingerprint(card).equals(entry.getString("fingerprint"))){state.put("at",at+1);state.put("skipped",state.optInt("skipped")+1);persist(state);continue;}a.ui(()->show(card));return;}JSONObject done=new JSONObject(state.toString());a.ui(()->finish(done));}catch(JSONException e){throw new IllegalStateException("Revisão guardada inválida.",e);}}
 static void advance(JSONObject s,int grade)throws JSONException{JSONArray grades=s.getJSONArray("grades");grades.put(grade,grades.getInt(grade)+1);s.put("at",s.getInt("at")+1);}
 static String interval(StudyStore.Row card,int grade){StudySchedule.Next next=StudySchedule.next(System.currentTimeMillis(),(int)card.n("interval"),(int)card.n("reps"),(int)card.n("lapses"),grade);return grade==0?"1 minuto":next.interval+ (next.interval==1?" dia":" dias");}
 void show(StudyStore.Row card){LinearLayout wrap=a.column();int at=state.optInt("at"),total=state.optJSONArray("queue").length();wrap.addView(a.label(state.optString("title")+" · "+(at+1)+" / "+total,12,a.muted));TextView front=new StudyUi(a).raw(card.s("front"),21,a.text);front.setMaxLines(Integer.MAX_VALUE);front.setTextIsSelectable(true);wrap.addView(front);wrap.addView(a.label("Tente recordar antes de revelar a resposta.",12,a.muted));TextView answer=a.label(card.s("back"),17,a.text);answer.setTextIsSelectable(true);answer.setVisibility(View.GONE);wrap.addView(answer);LinearLayout grades=a.column();grades.setVisibility(View.GONE);UiDialog dialog=(UiDialog)a.dialog().setTitle("Revisão activa").setView(wrap).setNegativeButton("Pausar e continuar depois",(d,w)->h.reload()).create();TextView reveal=a.primary("Mostrar resposta",()->{answer.setVisibility(View.VISIBLE);grades.setVisibility(View.VISIBLE);});reveal.setOnClickListener(v->{answer.setVisibility(View.VISIBLE);grades.setVisibility(View.VISIBLE);reveal.setVisibility(View.GONE);});wrap.addView(reveal);String[] labels={"Outra vez","Difícil","Recordei","Fácil"};AtomicBoolean chosen=new AtomicBoolean();for(int g=0;g<4;g++){final int grade=g;grades.addView(a.button(labels[g]+" · "+interval(card,g),()->{if(!chosen.compareAndSet(false,true))return;dialog.lock();h.job(()->{try{JSONObject next=new JSONObject(state.toString());h.db.grade(card.id(),grade,state.getString("token")+":"+at);advance(next,grade);persist(next);state=next;a.ui(dialog::dismiss);step();}catch(Exception e){a.ui(()->{dialog.dismiss();a.showError(e);});}});}));}wrap.addView(grades);if(card.n("material")>0)wrap.addView(a.button("Ver material de origem",()->{if(chosen.get())return;dialog.dismiss();h.job(()->{StudyStore.Row material=h.db.get("materials",card.n("material"));a.ui(()->{if(material==null)a.toast("O material de origem já não está disponível.");else h.openMaterial(material,true,(int)card.n("segment"));});});}));dialog.setOnCancelListener(d->h.reload());dialog.show();}
 void finish(JSONObject done){h.reload();JSONArray g=done.optJSONArray("grades");String info="Recordei: "+g.optInt(2)+"\nFácil: "+g.optInt(3)+"\nDifícil: "+g.optInt(1)+"\nOutra vez: "+g.optInt(0);if(done.optInt("skipped")>0)info+="\n\nIgnorados: "+done.optInt("skipped")+" (eliminados, alterados ou pausados).";a.dialog().setTitle("Sessão de revisão concluída").setMessage(info+"\n\nAs próximas datas foram guardadas. Estes resultados são a sua auto-avaliação.").setPositiveButton("Concluir",(d,w)->h.reload()).show();}
}
